def pick_port(used, low, high):
    for port in range(low, high):
        if port not in used:
            return port
    return None

def pick_port(used, low, high):
    for port in range(low, high + 1):
        if port not in used:
            return port
    return high

def pick_port(used, low, high):
    for port in range(high, low - 1, -1):
        if port not in used:
            return port
    return None

def pick_port(used, low, high):
    free = set(range(low, high + 1)) - set(used)
    if not free:
        return None
    return min(free)

