def luhn_valid(number):
    digits = "".join(ch for ch in number if ch not in " -")
    if not 12 <= len(digits) <= 19:
        return False
    if not (digits.isascii() and digits.isdigit()):
        return False
    total = 0
    for i, ch in enumerate(digits[::-1]):
        d = int(ch)
        if i % 2:
            tens, ones = divmod(d * 2, 10)
            d = tens + ones
        total += d
    return total % 10 == 0

_DOUBLED = [0, 2, 4, 6, 8, 1, 3, 5, 7, 9]


def luhn_valid(number):
    digits = number.translate({ord(" "): None, ord("-"): None})
    if len(digits) < 12 or len(digits) > 19:
        return False
    for ch in digits:
        if ch < "0" or ch > "9":
            return False
    total = 0
    flip = False
    for ch in reversed(digits):
        d = ord(ch) - 48
        total += _DOUBLED[d] if flip else d
        flip = not flip
    return total % 10 == 0

