import re

_PATTERN = re.compile(
    r" *(?:([0-9]+)d)? *(?:([0-9]+)h)? *(?:([0-9]+)m)? *(?:([0-9]+)s)? *"
)
_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(text):
    match = _PATTERN.fullmatch(text)
    if match is None or all(g is None for g in match.groups()):
        raise ValueError("invalid duration: %r" % (text,))
    return sum(
        int(g) * mult
        for g, mult in zip(match.groups(), _MULTIPLIERS)
        if g is not None
    )

import re


def parse_duration(text):
    s = text.strip(" ")
    if re.fullmatch(r"(?:[0-9]+[dhms] *)+", s) is None:
        raise ValueError("invalid duration: %r" % (text,))
    parts = re.findall(r"([0-9]+)([dhms])", s)
    order = ["d", "h", "m", "s"]
    positions = [order.index(unit) for _, unit in parts]
    if positions != sorted(set(positions)):
        raise ValueError("units out of order or repeated: %r" % (text,))
    factor = {"d": 24 * 60 * 60, "h": 60 * 60, "m": 60, "s": 1}
    return sum(int(num) * factor[unit] for num, unit in parts)
